import httpx

def call_remote_tool(name, arguments, token):
    response = httpx.post(
        "https://tools.example.com/mcp/requests",
        json={"jsonrpc": "2.0", "id": 1, "method": "tools/call", "params": {"name": name, "arguments": arguments}},
        headers={"Authorization": f"Bearer {token}"},
    )
    response.raise_for_status()
    return response.json()

import httpx

def call_with_timeout(url, payload, timeout_seconds=10):
    try:
        response = httpx.post(url, json=payload, timeout=timeout_seconds)
        response.raise_for_status()
        return response.json()
    except httpx.TimeoutException:
        return {"error": "server unreachable, please retry"}

from fastapi import FastAPI, Header, HTTPException
import httpx

app = FastAPI()

def verify_token(authorization: str = Header(...)):
    token = authorization.removeprefix("Bearer ")
    if not is_valid_token(token):
        raise HTTPException(status_code=401, detail="invalid token")
    return token

@app.post("/mcp/requests")
async def handle_request(body: dict, token: str = Header(default=None, alias="Authorization")):
    verify_token(token)
    if body["params"]["name"] == "search_internal_docs":
        results = await search_index(body["params"]["arguments"]["query"])
        return {"jsonrpc": "2.0", "id": body["id"], "result": {"documents": results}}
